def transform(grid):
    """Draw horizontal rays from each interior 1 toward the opposite edge."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    for r, c in seeds:
        # A seed's ray extends to either edge; endpoints preserve any guide color.
        left_wall = next((j for j in range(c - 1, -1, -1) if grid[r][j] not in (0, 1)), None)
        right_wall = next((j for j in range(c + 1, w) if grid[r][j] not in (0, 1)), None)
        if left_wall is not None and right_wall is not None:
            lo, hi = left_wall + 1, right_wall
            for j in range(lo, hi):
                if j != c:
                    out[r][j] = 1
            out[r][c] = 4
        elif left_wall is not None:
            for j in range(left_wall + 1, c): out[r][j] = 1
            out[r][c] = 4
        elif right_wall is not None:
            for j in range(c + 1, right_wall): out[r][j] = 1
            out[r][c] = 4
        else:
            for j in range(c):
                if out[r][j] == 0: out[r][j] = 1
            out[r][c] = 4
    # Edge guide segments continue horizontally across the adjacent rows.
    for c in range(w):
        if grid[0][c] == 1:
            for r in range(0, h):
                if grid[r][c] == 0: out[r][c] = 1
        if grid[h-1][c] == 1:
            for r in range(h-1, -1, -1):
                if grid[r][c] == 0: out[r][c] = 1
    return out
