def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def runs(line):
        ans=[]; i=0
        while i<len(line):
            if line[i]==bg:
                i+=1; continue
            col=line[i]; j=i+1
            while j<len(line) and line[j]==col: j+=1
            ans.append((i,j,col)); i=j
        return ans

    candidates=[]
    for axis, first, second in (
        ('lr', runs([grid[r][0] for r in range(h)]),
         runs([grid[r][-1] for r in range(h)])),
        ('tb', runs(grid[0]), runs(grid[-1]))):
        for a in first:
            for b in second:
                if a[2]==b[2] and a[1]-a[0]==b[1]-b[0]:
                    candidates.append((a[1]-a[0],axis,a,b))
    if not candidates:
        return out
    _,axis,a,b=max(candidates,key=lambda x:x[0])
    a0,a1,wall=a; b0,b1,_=b
    # Select non-background markers excluding the paired border bars.
    if axis=='lr':
        bar={(r,0) for r in range(a0,a1)} | {(r,w-1) for r in range(b0,b1)}
    else:
        bar={(0,c) for c in range(a0,a1)} | {(h-1,c) for c in range(b0,b1)}
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in bar: continue
            if axis=='tb':
                if b0<=c<b1:
                    # Lower-edge span paired with upper span, reversed along the perimeter.
                    mate=a1-1-(c-b0)
                    out[r][c]=4
                    for rr in range(r+1,h-1):
                        if grid[rr][c]==bg: out[rr][c]=color
                    for rr in range(1,h-1):
                        if grid[rr][mate]==bg: out[rr][mate]=color
                elif a0<=c<a1:
                    mate=b1-1-(c-a0)
                    out[r][c]=4
                    for rr in range(r-1,0,-1):
                        if grid[rr][c]==bg: out[rr][c]=color
                    for rr in range(1,h-1):
                        if grid[rr][mate]==bg: out[rr][mate]=color
            else:
                if a0<=r<a1:
                    mate=b0+(r-a0)
                    out[r][c]=4
                    for cc in range(c-1,0,-1):
                        if grid[r][cc]==bg: out[r][cc]=color
                    for cc in range(1,w-1):
                        if grid[mate][cc]==bg: out[mate][cc]=color
                elif b0<=r<b1:
                    mate=a0+(r-b0)
                    out[r][c]=4
                    for cc in range(c+1,w-1):
                        if grid[r][cc]==bg: out[r][cc]=color
                    for cc in range(1,w-1):
                        if grid[mate][cc]==bg: out[mate][cc]=color
    return out
